const { spawnSync } = require("node:child_process");
const r = spawnSync(process.execPath, ["main.ts"], { encoding: "utf8" });
if (r.status !== 0) {
  console.error("main.ts exited with", r.status, r.stderr.slice(0, 400));
  process.exit(1);
}
if (r.stdout.trim() !== "42") {
  console.error("unexpected output:", JSON.stringify(r.stdout.trim()));
  process.exit(1);
}
